export function solve(s) {
  const st = [];
  const pairs = { ")": "(", "]": "[", "}": "{" };

  for (const c of s) {
    if ("([{".includes(c)) {
      st.push(c);
    } else if (st.pop() !== pairs[c]) {
      return false;
    }
  }

  return st.length === 0;
}
```

The stack tracks unmatched opening brackets in nesting order. Success now requires that stack to be empty: `"("` returns `false`, while empty input remains valid. The synchronous API and dependency-free usage are unchanged.

